import { supabase as base } from './mobileV19Supabase.js';
export const availableFixture = { fail:false, empty:false, requests:[] };
const rows=Array.from({length:600},(_,i)=>({id:`m-${i}`,venue_id:'K1',da_riportare:1,recupero:0,deleted_at:null,work_date:'2026-10-08'}));
rows.push({id:'recovery',venue_id:'K1',da_riportare:0,recupero:100,deleted_at:null,work_date:'2026-10-08'}, {id:'negative',venue_id:'K2',da_riportare:100,recupero:200,deleted_at:null,work_date:'2026-10-08'}, {id:'deleted',venue_id:'K2',da_riportare:10000,recupero:0,deleted_at:'2026-10-08',work_date:'2026-10-08'}, {id:'old',venue_id:'K2',da_riportare:10000,recupero:0,deleted_at:null,work_date:'2026-09-01'});
function query(table){let fields='',start=0,end=Infinity,one=false;const filters=[];const q={select(f){fields=f;return q;},order(){return q;},eq(k,v){filters.push(r=>r[k]===v);return q;},neq(k,v){filters.push(r=>r[k]!==v);return q;},range(a,b){start=a;end=b;return q;},maybeSingle(){one=true;return q;},is(k,v){filters.push(r=>(r[k]??null)===v);return q;},gte(k,v){filters.push(r=>r[k]>=v);return q;},lte(k,v){filters.push(r=>r[k]<=v);return q;},then(resolve,reject){availableFixture.requests.push({table,start,end,fields});if(availableFixture.fail&&fields.includes('recupero'))return Promise.resolve({data:null,error:{message:'Rete non disponibile'}}).then(resolve,reject);const data=table==='active_conteggi_period'?[{id:'period',date_from:'2026-10-01',date_to:'2026-10-16'}]:table==='venues'?[{id:'K1',name:'ROXY BAR'},{id:'K2',name:'ALTRO LOCALE'}]:availableFixture.empty?[]:rows;const out=data.filter(r=>filters.every(f=>f(r))).slice(start,end+1);return Promise.resolve({data:one?out[0]:out,error:null}).then(resolve,reject);}};return q;}
export const supabase={...base,from:table=>['active_conteggi_period','venues','movements_cassa'].includes(table)?query(table):base.from(table)};
